const PAGE_ID = '1348081288382156';
let out = { route:'skip', reason:'', commentId:'', authorId:'', authorName:'', text:'', postId:'', permalink:'', source:'facebook' };
try {
  const items = $input.all();
  const p = (items && items[0] && items[0].json) ? items[0].json : {};
  let data = p.payload || p.body || p;
  if (typeof data === 'string') { data = JSON.parse(data); }
  if (!data || typeof data !== 'object') { data = {}; }
  const entries = Array.isArray(data.entry) ? data.entry : [];
  for (const en of entries) {
    const chs = Array.isArray(en.changes) ? en.changes : [];
    for (const ch of chs) {
      if (ch.field !== 'feed') { continue; }
      const v = ch.value || {};
      const from = v.from || {};
      const authorId = String(from.id || '');
      const text = String(v.message || '').slice(0, 2000);
      const low = text.toLowerCase();
      if (authorId === PAGE_ID) { out.route='skip'; out.reason='self-page'; continue; }
      if (v.item !== 'comment' || v.verb !== 'add') { out.route='skip'; out.reason='not-new-comment'; continue; }
      if (low.indexOf('aqui tienes el link') >= 0 || low.indexOf('gracias') >= 0) { out.route='skip'; out.reason='own-reply-text'; continue; }
      if (low.indexOf('link') < 0 && low.indexOf('enlace') < 0) { out.route='skip'; out.reason='no-keyword'; continue; }
      out.route='lead'; out.reason='match';
      out.commentId = String(v.comment_id || v.id || '');
      out.authorId = authorId;
      out.authorName = from.name || 'facebook-lead';
      out.text = text;
      out.postId = String(v.post_id || (v.post && v.post.id) || '');
      out.permalink = String((v.post && v.post.permalink_url) || '');
    }
  }
} catch (err) { out.route='skip'; out.reason='error'; }
return [{ json: out }];

const d = $input.first().json;
const now = new Date().toISOString();
const n = d.authorName || 'facebook-lead';
return [{ json: { externalId:d.commentId, userId:d.authorId, name:n, message:d.text||'', postId:d.postId||'', permalink:d.permalink||'', source:'facebook', sourceCrm:'zoho', sourceClient:'growbusy-main', consent:{ emailMarketing:false, smsMarketing:false, version:'v1', capturedAt:now }, capturedAt:now } }];

// Loud, but never at the customer's expense.
//
// The reply node is set to continue-on-error so a failed public reply still
// lets the DM through — the person still gets the link. This node runs last
// and re-raises, so the failure is still loud in n8n instead of hiding behind
// a green execution.
const items = $input.all();
const failed = items.filter((i) => i && i.json && i.json.error !== undefined && i.json.error !== null);
if (failed.length) {
  const detail = failed.map((i) => (typeof i.json.error === 'string' ? i.json.error : JSON.stringify(i.json.error))).join(' | ');
  throw new Error('Public reply to the social comment failed; downstream delivery was still attempted: ' + detail);
}
return items;

